 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../contexts/ToastContext'
import { Link } from 'react-router-dom'
import { 
  Calendar, 
  Plus, 
  Minus, 
  Trash2, 
  Send, 
  XCircle,
  Home as HomeIcon,
  Plane,
  Globe,
  Lock
} from 'lucide-react'
import { footballApi, getTeamEmoji } from '../services/footballApi'

export default function Slip() {
    const { user, profile } = useAuth()
    const { showToast } = useToast()
    const [matches, setMatches] = useState([])
    const [loading, setLoading] = useState(true)
    const [slip, setSlip] = useState([])
    const [selectedOutcomes, setSelectedOutcomes] = useState({})
    const [shareModalOpen, setShareModalOpen] = useState(false)
    const [shareType, setShareType] = useState('public')
    const [userCommunities, setUserCommunities] = useState([])
    const [selectedCommunity, setSelectedCommunity] = useState('')
    const [comment, setComment] = useState('')

    useEffect(() => {
        loadMatches()
        if (user) {
            loadUserCommunities()
        }
        const savedSlip = localStorage.getItem('predictfc_slip')
        if (savedSlip) {
            try {
                const parsed = JSON.parse(savedSlip)
                setSlip(parsed)
                const outcomes = {}
                parsed.forEach(item => {
                    outcomes[item.matchId] = item.outcome
                })
                setSelectedOutcomes(outcomes)
            } catch (e) {
                console.error('Error loading slip:', e)
            }
        }
    }, [user])

    useEffect(() => {
        localStorage.setItem('predictfc_slip', JSON.stringify(slip))
    }, [slip])

    const loadMatches = async () => {
        setLoading(true)
        try {
            const events = await footballApi.getTodaysMatches()
            setMatches(events)
        } catch (error) {
            console.error('Error loading matches:', error)
            showToast('Failed to load matches', 'error')
        } finally {
            setLoading(false)
        }
    }

    const loadUserCommunities = async () => {
        try {
            const { data } = await supabase
                .from('communities')
                .select('id, name')
                .eq('creator_id', user?.id)
            setUserCommunities(data || [])
            if (data?.length > 0) {
                setSelectedCommunity(data[0].id)
            }
        } catch (error) {
            console.error('Error loading communities:', error)
        }
    }

    const addToSlip = (match) => {
        if (slip.some(item => item.matchId === match.idEvent)) {
            showToast('Already in slip', 'info')
            return
        }

        const newEntry = {
            matchId: match.idEvent,
            homeTeam: match.strHomeTeam || 'Home',
            awayTeam: match.strAwayTeam || 'Away',
            outcome: 'Draw',
            league: match.strLeague || 'Unknown',
            match: match
        }

        setSlip([...slip, newEntry])
        setSelectedOutcomes({
            ...selectedOutcomes,
            [match.idEvent]: 'Draw'
        })
        showToast(`Added ${newEntry.homeTeam} vs ${newEntry.awayTeam}`, 'success')
    }

    const removeFromSlip = (matchId) => {
        setSlip(slip.filter(item => item.matchId !== matchId))
        const newOutcomes = { ...selectedOutcomes }
        delete newOutcomes[matchId]
        setSelectedOutcomes(newOutcomes)
    }

    const updateOutcome = (matchId, outcome) => {
        setSelectedOutcomes({
            ...selectedOutcomes,
            [matchId]: outcome
        })
        setSlip(slip.map(item => 
            item.matchId === matchId ? { ...item, outcome } : item
        ))
    }

    const clearSlip = () => {
        if (window.confirm('Clear all selections?')) {
            setSlip([])
            setSelectedOutcomes({})
            localStorage.removeItem('predictfc_slip')
        }
    }

    const handleShare = async () => {
        if (slip.length === 0) {
            showToast('Add at least one match', 'warning')
            return
        }

        try {
            const slipText = `📊 My Bet Slip:\n${slip.map(item => 
                `• ${item.homeTeam} vs ${item.awayTeam}: ${item.outcome}`
            ).join('\n')}`

            const fullText = comment ? `${comment}\n\n${slipText}` : slipText

            if (shareType === 'public') {
                const { error } = await supabase
                    .from('posts')
                    .insert({
                        user_id: user.id,
                        text: fullText,
                        likes_count: 0,
                        comments_count: 0
                    })

                if (error) throw error
                showToast('Slip shared to Feed!', 'success')
            } else {
                if (!selectedCommunity) {
                    showToast('Please select a community', 'error')
                    return
                }

                const { error } = await supabase
                    .from('community_posts')
                    .insert({
                        community_id: selectedCommunity,
                        user_id: user.id,
                        text: fullText
                    })

                if (error) throw error
                showToast('Slip shared to Community!', 'success')
            }

            setSlip([])
            setSelectedOutcomes({})
            setComment('')
            localStorage.removeItem('predictfc_slip')
            setShareModalOpen(false)

        } catch (error) {
            console.error('Error sharing slip:', error)
            showToast('Failed to share slip', 'error')
        }
    }

    const getOutcomeEmoji = (outcome) => {
        switch(outcome) {
            case 'Home Win': return '🏠'
            case 'Away Win': return '✈️'
            case 'Draw': return '🤝'
            default: return '📊'
        }
    }

    return (
        <div className="max-w-6xl mx-auto px-4 py-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                        <Calendar size={24} /> Bet Slip
                    </h1>
                    <p className="text-gray-400 text-sm">Select matches and predict the outcome</p>
                </div>
                {slip.length > 0 && (
                    <div className="flex gap-2">
                        <span className="px-3 py-1.5 bg-gray-100 text-gray-700 rounded-lg text-sm font-medium">
                            {slip.length} selections
                        </span>
                        <button
                            onClick={() => setShareModalOpen(true)}
                            className="px-4 py-1.5 bg-gray-800 text-white rounded-lg hover:bg-gray-900 transition text-sm flex items-center gap-1"
                        >
                            <Send size={16} /> Share
                        </button>
                        <button
                            onClick={clearSlip}
                            className="px-4 py-1.5 bg-gray-100 text-gray-600 rounded-lg hover:bg-gray-200 transition text-sm flex items-center gap-1"
                        >
                            <Trash2 size={16} /> Clear
                        </button>
                    </div>
                )}
            </div>

            <div className="grid lg:grid-cols-3 gap-6">
                {/* Matches List */}
                <div className="lg:col-span-2">
                    {loading ? (
                        <div className="text-center py-12 text-gray-400">Loading matches...</div>
                    ) : matches.length === 0 ? (
                        <div className="text-center py-12 bg-white rounded-xl shadow-sm border border-gray-100">
                            <Calendar className="w-16 h-16 text-gray-200 mx-auto mb-4" />
                            <p className="text-gray-400">No matches available</p>
                        </div>
                    ) : (
                        <div className="space-y-3">
                            {matches.map((match) => {
                                const inSlip = slip.some(item => item.matchId === match.idEvent)
                                const homeEmoji = getTeamEmoji(match.strHomeTeam)
                                const awayEmoji = getTeamEmoji(match.strAwayTeam)
                                
                                return (
                                    <div key={match.idEvent} className={`bg-white rounded-xl shadow-sm border p-4 transition ${inSlip ? 'border-gray-400' : 'border-gray-100'}`}>
                                        <div className="flex items-center justify-between">
                                            <div className="flex-1">
                                                <div className="text-xs text-gray-400 font-medium mb-1">
                                                    {match.strLeague || 'Unknown League'}
                                                </div>
                                                <div className="flex items-center gap-4">
                                                    <div className="flex items-center gap-2 min-w-[100px]">
                                                        <span className="text-2xl">{homeEmoji}</span>
                                                        <span className="font-medium text-gray-800">{match.strHomeTeam || 'Home'}</span>
                                                    </div>
                                                    <span className="text-gray-400 text-sm">vs</span>
                                                    <div className="flex items-center gap-2 min-w-[100px]">
                                                        <span className="font-medium text-gray-800">{match.strAwayTeam || 'Away'}</span>
                                                        <span className="text-2xl">{awayEmoji}</span>
                                                    </div>
                                                </div>
                                                <div className="text-xs text-gray-400 mt-1">
                                                    {match.dateEvent ? new Date(match.dateEvent).toLocaleDateString() : ''}
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                {inSlip ? (
                                                    <button
                                                        onClick={() => removeFromSlip(match.idEvent)}
                                                        className="px-3 py-1.5 bg-gray-100 text-red-500 rounded-lg hover:bg-gray-200 transition text-sm flex items-center gap-1"
                                                    >
                                                        <Minus size={14} /> Remove
                                                    </button>
                                                ) : (
                                                    <button
                                                        onClick={() => addToSlip(match)}
                                                        className="px-3 py-1.5 bg-gray-800 text-white rounded-lg hover:bg-gray-900 transition text-sm flex items-center gap-1"
                                                    >
                                                        <Plus size={14} /> Add
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </div>

                {/* Slip Panel */}
                <div>
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 sticky top-20">
                        <h3 className="font-bold text-gray-800 mb-3 flex items-center gap-2">
                            <Calendar size={18} /> Your Slip
                            {slip.length > 0 && (
                                <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">
                                    {slip.length}
                                </span>
                            )}
                        </h3>

                        {slip.length === 0 ? (
                            <div className="text-center py-8 text-gray-400">
                                <Calendar className="w-12 h-12 mx-auto mb-2 text-gray-200" />
                                <p className="text-sm">No selections yet</p>
                                <p className="text-xs">Add matches from the list</p>
                            </div>
                        ) : (
                            <div className="space-y-3 max-h-[400px] overflow-y-auto">
                                {slip.map((item) => (
                                    <div key={item.matchId} className="border-b border-gray-100 pb-2">
                                        <div className="flex justify-between items-start">
                                            <div className="flex-1">
                                                <div className="text-xs font-medium text-gray-700">
                                                    {item.homeTeam} vs {item.awayTeam}
                                                </div>
                                                <div className="flex items-center gap-2 mt-1">
                                                    <button
                                                        onClick={() => updateOutcome(item.matchId, 'Home Win')}
                                                        className={`px-2 py-0.5 text-xs rounded transition ${
                                                            selectedOutcomes[item.matchId] === 'Home Win'
                                                                ? 'bg-gray-800 text-white'
                                                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                                        }`}
                                                    >
                                                        🏠 Home
                                                    </button>
                                                    <button
                                                        onClick={() => updateOutcome(item.matchId, 'Draw')}
                                                        className={`px-2 py-0.5 text-xs rounded transition ${
                                                            selectedOutcomes[item.matchId] === 'Draw'
                                                                ? 'bg-gray-800 text-white'
                                                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                                        }`}
                                                    >
                                                        🤝 Draw
                                                    </button>
                                                    <button
                                                        onClick={() => updateOutcome(item.matchId, 'Away Win')}
                                                        className={`px-2 py-0.5 text-xs rounded transition ${
                                                            selectedOutcomes[item.matchId] === 'Away Win'
                                                                ? 'bg-gray-800 text-white'
                                                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                                        }`}
                                                    >
                                                        ✈️ Away
                                                    </button>
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => removeFromSlip(item.matchId)}
                                                className="text-gray-400 hover:text-red-500 text-xs"
                                            >
                                                <XCircle size={14} />
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        {slip.length > 0 && (
                            <button
                                onClick={() => setShareModalOpen(true)}
                                className="w-full mt-3 py-2 bg-gray-800 text-white rounded-lg hover:bg-gray-900 transition flex items-center justify-center gap-1 text-sm"
                            >
                                <Send size={16} /> Share Slip
                            </button>
                        )}
                    </div>
                </div>
            </div>

            {/* Share Modal */}
            {shareModalOpen && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xl font-bold text-gray-800">Share Bet Slip</h3>
                            <button 
                                onClick={() => setShareModalOpen(false)}
                                className="text-gray-400 hover:text-gray-600 text-2xl"
                            >
                                ×
                            </button>
                        </div>

                        <div className="mb-4">
                            <label className="block text-sm font-medium text-gray-700 mb-2">Where to share?</label>
                            <div className="grid grid-cols-2 gap-2">
                                <button
                                    onClick={() => setShareType('public')}
                                    className={`py-2 rounded-lg text-sm font-medium transition flex items-center justify-center gap-2 ${
                                        shareType === 'public'
                                            ? 'bg-gray-800 text-white'
                                            : 'border border-gray-300 text-gray-700 hover:bg-gray-50'
                                    }`}
                                >
                                    <Globe size={16} /> Feed
                                </button>
                                <button
                                    onClick={() => setShareType('private')}
                                    className={`py-2 rounded-lg text-sm font-medium transition flex items-center justify-center gap-2 ${
                                        shareType === 'private'
                                            ? 'bg-gray-800 text-white'
                                            : 'border border-gray-300 text-gray-700 hover:bg-gray-50'
                                    }`}
                                >
                                    <Lock size={16} /> Community
                                </button>
                            </div>
                        </div>

                        {shareType === 'private' && (
                            <div className="mb-4">
                                <label className="block text-sm font-medium text-gray-700 mb-2">Choose Community</label>
                                <select
                                    value={selectedCommunity}
                                    onChange={(e) => setSelectedCommunity(e.target.value)}
                                    className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-400 bg-white text-gray-800"
                                >
                                    {userCommunities.map(c => (
                                        <option key={c.id} value={c.id}>{c.name}</option>
                                    ))}
                                </select>
                            </div>
                        )}

                        <div className="mb-4">
                            <label className="block text-sm font-medium text-gray-700 mb-2">Add a comment (optional)</label>
                            <textarea
                                value={comment}
                                onChange={(e) => setComment(e.target.value)}
                                placeholder="What do you think about these matches?"
                                className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-400 bg-white text-gray-800 resize-none"
                                rows="3"
                            />
                        </div>

                        <div className="bg-gray-50 rounded-lg p-3 mb-4 border border-gray-100">
                            <div className="text-sm font-medium text-gray-700 mb-1">Preview</div>
                            <div className="text-sm text-gray-600">
                                {slip.map(item => (
                                    <div key={item.matchId} className="flex items-center gap-2">
                                        <span>{item.homeTeam} vs {item.awayTeam}</span>
                                        <span className="text-xs font-medium text-gray-800">→ {selectedOutcomes[item.matchId] || 'Draw'}</span>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <button
                            onClick={handleShare}
                            className="w-full bg-gray-800 text-white py-2 rounded-lg hover:bg-gray-900 transition flex items-center justify-center gap-1"
                        >
                            <Send size={16} /> Share Slip
                        </button>
                    </div>
                </div>
            )}
        </div>
    )
}
